import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"introduction.md","filePath":"introduction.md","lastUpdated":1792298797000}`),a={name:`introduction.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h1><p>曦寒流程设计器（XiHan.FlowDesigner）是一款框架无关的流程设计器：以原生 Web Components 交付，用查看器显示流程与每个节点的运行状态，用设计器可视化编辑流程。节点类型、属性、校验规则、渲染、命令与面板都经扩展登记；自带 XiHan.Framework 工作流引擎的节点预设，流程定义能与引擎定义互相转换。属于曦寒懿（XiHanFun）开源生态，采用 MIT 授权。</p><h2 id="能做什么" tabindex="-1">能做什么 <a class="header-anchor" href="#能做什么" aria-label="Permalink to “能做什么”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>用什么</th></tr></thead><tbody><tr><td>在业务页面里显示流程与运行进度</td><td><code>&lt;xh-flow-viewer&gt;</code>：按节点类型画出流程，标出运行状态与高亮，缩放、平移、定位节点</td></tr><tr><td>设计与修改流程</td><td><code>&lt;xh-flow-designer&gt;</code>：物料拖放、连线与改连、对齐吸附、属性面板、问题列表、小地图、撤销重做与剪贴板</td></tr><tr><td>在服务端或脚本里检查流程定义</td><td><code>@xihan-flow/core</code> 的 <code>readDocument</code> 与 <code>validateDocument</code>，不依赖 DOM</td></tr><tr><td>对接 XiHan 工作流引擎</td><td><code>@xihan-flow/core/presets/xihan-workflow</code>：引擎活动对应的节点类型，与引擎定义 JSON 互转</td></tr></tbody></table><h2 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to “设计原则”">​</a></h2><ul><li><strong>框架无关</strong>：以原生 Web Components 交付，不绑定任何前端框架。元素用 Light DOM，样式只消费 <a href="https://ui.docs.xihanfun.com" target="_blank" rel="noreferrer">XiHan.UI</a> 的设计令牌。</li><li><strong>零第三方依赖</strong>：运行时只依赖 <code>@xihan-flow/*</code> 与 <code>@xihan-ui/*</code>，布局、连线路由、指针手势与设计器的外框、面板都来自 XiHan.UI。</li><li><strong>流程定义即数据</strong>：流程定义是纯 JSON，不含也不执行任何代码；读入时逐项检查结构，带问题的定义不会被当成合法数据。</li><li><strong>一切经扩展登记</strong>：节点类型、属性、编辑方式、校验规则、渲染、命令与面板都由按实例传入的扩展登记。名字冲突在赋值时当场报错，去掉一个扩展就撤掉它带来的一切。</li><li><strong>数据由使用方掌控</strong>：组件不发网络请求。流程定义存在哪里、谁能改，都由使用方决定，经属性与事件交给组件。</li><li><strong>没有全局状态</strong>：不往 <code>window</code> 上挂对象，不读写固定键名的本地存储，同一页面放多个实例互不影响。</li></ul><h2 id="包与入口" tabindex="-1">包与入口 <a class="header-anchor" href="#包与入口" aria-label="Permalink to “包与入口”">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>内容</th></tr></thead><tbody><tr><td><code>@xihan-flow/core</code></td><td>流程定义的类型、读入检查、校验、编辑操作、连线几何、节点类型登记与扩展合并。纯 TypeScript，不依赖 DOM，浏览器与 Node.js 里都能用</td></tr><tr><td><code>@xihan-flow/core/presets/xihan-workflow</code></td><td>XiHan 工作流引擎的节点预设，以及流程定义与引擎定义的互转</td></tr><tr><td><code>@xihan-flow/runtime</code></td><td>业务页面用的 <code>&lt;xh-flow-viewer&gt;</code> 与直角连线路由，样式在 <code>@xihan-flow/runtime/style.css</code></td></tr><tr><td><code>@xihan-flow/runtime/locale</code></td><td>语言包 <code>flowZhCN</code>、<code>flowJaJP</code> 等，与 XiHan.UI 的语言包一一对应，查看器与设计器共用</td></tr><tr><td><code>@xihan-flow/designer</code></td><td><code>&lt;xh-flow-designer&gt;</code>，样式在 <code>@xihan-flow/designer/style.css</code></td></tr></tbody></table><p>依赖方向固定为 <code>designer → runtime → core</code>。业务页面只需要 runtime，设计器只在需要编辑流程的地方加载。</p><h2 id="工作流程" tabindex="-1">工作流程 <a class="header-anchor" href="#工作流程" aria-label="Permalink to “工作流程”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>设计器 &lt;xh-flow-designer&gt;</span></span>
<span class="line"><span>  │  schema-change / save 事件</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>宿主保存流程定义 JSON（数据库、文件，由宿主决定）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ 业务页面取出流程定义与运行状态 ──▶ &lt;xh-flow-viewer&gt; 显示进度</span></span>
<span class="line"><span>  └─ 用 XiHan 工作流引擎时转成引擎定义 ──▶ 引擎发布与运行</span></span></code></pre></div><ol><li>设计：在设计器里编辑流程，设计器派发 <code>schema-change</code> 与 <code>save</code>，宿主把流程定义存起来。</li><li>查看：业务页面取出流程定义与各节点的运行状态，交给查看器显示。</li><li>运行：用 XiHan 工作流引擎时，用预设把流程定义转成引擎定义交给引擎；从引擎取回的定义也能转回流程定义继续编辑。</li></ol><h2 id="运行环境" tabindex="-1">运行环境 <a class="header-anchor" href="#运行环境" aria-label="Permalink to “运行环境”">​</a></h2><ul><li><code>@xihan-flow/core</code> 不依赖 DOM，可以在浏览器、Node.js 或其它 JavaScript 运行环境里读入与校验流程定义。</li><li><code>@xihan-flow/runtime</code> 与 <code>@xihan-flow/designer</code> 要在支持 Custom Elements 的浏览器里运行。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./quickstart">快速开始</a>：在任意前端项目里装包，显示一张审批流并标出运行状态。</li><li><a href="./guide/schema">流程定义结构</a>：节点、连线、业务数据与扩展数据，读入、校验与编辑操作。</li><li><a href="./guide/viewer">查看器</a>：运行状态、高亮、定位、事件与自定义节点内容。</li><li><a href="./guide/designer">设计器</a>：编辑、属性面板、问题列表、命令、撤销与保存。</li><li><a href="./guide/extensions">扩展</a>：节点类型、属性、编辑方式、规则、属性编辑器、命令与面板。</li><li><a href="./guide/xihan-workflow">XiHan 工作流引擎预设</a>：引擎活动对应的节点类型、受理人规则，以及与引擎定义互转。</li><li><a href="./guide/host">与宿主集成</a>：打开与保存、运行状态、权限、服务端复核与在前端框架里使用。</li></ul>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};